media_identity_v1111:
"""v1.11.1 多来源媒体身份门禁纯函数。

原则：明确冲突硬拒绝；信息缺失不直接判错。搜索卡片只能作为弱证据，
必须与实际分享/解析后的文件结构共同达到置信度阈值，避免为了防错显著降低秒传成功率。
"""
from __future__ import annotations

import html
import re
from pathlib import PurePosixPath
from typing import Any, Dict, Iterable, List, Sequence, Set

_TECH_TOKEN_RE = re.compile(
    r"(?ix)^(?:2160p|1080p|1080i|720p|576p|480p|4k|8k|web(?:dl|rip)?|web-dl|dl|bluray|blu-ray|bdrip|brrip|remux|hdtv|uhd|x26[45]|h26[45]|hevc|avc|av1|10bit|8bit|hdr10\+?|hdr|dv|dolbyvision|aac\d?(?:\.\d)?|ac3|eac3|ddp?\d?(?:\.\d)?|dts(?:hd)?|truehd|atmos|flac|proper|repack|rerip|internal|extended|uncut|complete|全集|全季|chs|cht|chi|eng|jpn|kor|multi|dual|字幕|中字|简中|繁中)$"
)
_EP_TOKEN_RE = re.compile(r"(?i)^(?:s\d{1,2}(?:e\d{1,4})?|e\d{1,4}|ep\d{1,4}|episode\d{1,4})$")
_EPISODE_EVIDENCE_RE = re.compile(
    r"(?i)(?:\bS\d{1,2}[ ._\-]*E\d{1,4}\b|\b(?:E|EP|Episode)[ ._\-]*0*\d{1,4}\b|第\s*\d{1,4}\s*(?:集|话))"
)
_SEASON_PATTERNS = (
    re.compile(r"(?i)\bS(?:eason)?[ ._\-]*0*(\d{1,2})(?=E|[^0-9]|$)"),
    re.compile(r"第\s*0*(\d{1,2})\s*季"),
)
_YEAR_RE = re.compile(r"(?<!\d)(19\d{2}|20\d{2})(?!\d)")
_CJK_SEASON_RE = re.compile(r"第\s*([一二三四五六七八九十]{1,3})\s*季")
_GENERIC_PRIMARY_KEYS = {
    "file", "files", "video", "movie", "tv", "season", "download", "resource", "share",
    "资源", "文件", "视频", "电影", "电视剧", "剧集", "分享", "迅雷", "云盘", "迅雷云盘",
    "迅雷分享", "云盘分享", "资源分享", "迅雷云盘分享",
}


def _cn_number(value: str) -> int:
    digits = {"一": 1, "二": 2, "三": 3, "四": 4, "五": 5, "六": 6, "七": 7, "八": 8, "九": 9}
    if value == "十":
        return 10
    if "十" in value:
        left, _, right = value.partition("十")
        return (digits.get(left, 1) * 10) + digits.get(right, 0)
    return digits.get(value, 0)


def explicit_seasons_v1111(values: Iterable[Any]) -> Set[int]:
    seasons: Set[int] = set()
    for raw in values or []:
        text = html.unescape(str(raw or ""))
        for pattern in _SEASON_PATTERNS:
            for match in pattern.findall(text):
                try:
                    number = int(match)
                except (TypeError, ValueError):
                    continue
                if 0 <= number <= 99:
                    seasons.add(number)
        for token in _CJK_SEASON_RE.findall(text):
            number = _cn_number(token)
            if 0 < number <= 99:
                seasons.add(number)
    return seasons


def _title_year_tokens(aliases: Sequence[str]) -> Set[str]:
    result: Set[str] = set()
    for alias in aliases or []:
        result.update(_YEAR_RE.findall(str(alias or "")))
    return result


def explicit_years_v1111(values: Iterable[Any], aliases: Sequence[str] = ()) -> Set[str]:
    title_numbers = _title_year_tokens(aliases)
    years: Set[str] = set()
    for raw in values or []:
        for token in _YEAR_RE.findall(html.unescape(str(raw or ""))):
            if token not in title_numbers:
                years.add(token)
    return years


def _candidate_strings(value: Any) -> List[str]:
    text = html.unescape(str(value or "")).replace("\\", "/").strip()
    if not text:
        return []
    rows = [text]
    rows.extend(part.strip() for part in text.splitlines() if part.strip())
    rows.extend(part.strip() for part in re.split(r"[|／]", text) if part.strip())
    try:
        path = PurePosixPath(text)
        rows.extend(part for part in path.parts if part not in {"/", ".", ".."})
        rows.append(path.name)
    except Exception:
        pass
    result: List[str] = []
    seen = set()
    for row in rows:
        key = row.casefold()
        if row and key not in seen:
            seen.add(key)
            result.append(row)
    return result


def title_key_v1111(value: Any, expected_year: Any = None) -> str:
    text = html.unescape(str(value or ""))
    text = re.sub(r"<[^>]+>", " ", text)
    text = re.sub(r"\.(?:mkv|mp4|ts|m2ts|avi|mov|wmv|flv|webm|iso|m4v|srt|ass|ssa|vtt|sup)$", " ", text, flags=re.I)
    text = re.sub(r"[\[【（(][^\]】）)]{0,80}[\]】）)]", " ", text)
    text = re.sub(r"(?i)\bS(?:eason)?[ ._\-]*0*\d{1,2}(?:[ ._\-]*E(?:pisode)?[ ._\-]*0*\d{1,4})?(?=[^0-9A-Za-z]|$)", " ", text)
    text = re.sub(r"(?i)\b(?:E|EP|Episode)[ ._\-]*0*\d{1,4}\b", " ", text)
    text = re.sub(r"第\s*[0-9一二三四五六七八九十]{1,3}\s*(?:季|集|话)", " ", text)
    year = str(expected_year or "").strip()
    if year and re.fullmatch(r"(?:19|20)\d{2}", year):
        text = re.sub(rf"(?<!\d){re.escape(year)}(?!\d)", " ", text)
    raw_tokens = [token for token in re.split(r"[^0-9A-Za-z\u4e00-\u9fff]+", text) if token]
    kept: List[str] = []
    for token in raw_tokens:
        lowered = token.casefold()
        if _TECH_TOKEN_RE.fullmatch(lowered) or _EP_TOKEN_RE.fullmatch(lowered):
            continue
        if lowered in {"2160", "1080", "720", "576", "480", "264", "265"}:
            continue
        kept.append(lowered)
    return "".join(kept)


def title_variants_v1111(value: Any, expected_year: Any = None) -> Set[str]:
    variants: Set[str] = set()
    for candidate in _candidate_strings(value):
        key = title_key_v1111(candidate, expected_year=expected_year)
        if len(key) >= 2:
            variants.add(key)
    return variants


def strong_title_match_v1111(expected: Any, actual: Any, expected_year: Any = None) -> bool:
    wanted = title_variants_v1111(expected, expected_year=expected_year)
    found = title_variants_v1111(actual, expected_year=expected_year)
    return bool(wanted and found and wanted.intersection(found))


def any_alias_title_match_v1111(aliases: Sequence[str], evidences: Iterable[Any], expected_year: Any = None) -> bool:
    alias_keys: Set[str] = set()
    for alias in aliases or []:
        alias_keys.update(title_variants_v1111(alias, expected_year=expected_year))
    if not alias_keys:
        return False
    for evidence in evidences or []:
        if alias_keys.intersection(title_variants_v1111(evidence, expected_year=expected_year)):
            return True
    return False


def _rows_v1111(values: Iterable[Any]) -> List[str]:
    return [str(value or "").strip() for value in values or [] if str(value or "").strip()]


def _credible_primary_title_v1111(values: Iterable[Any], expected_year: Any = None) -> bool:
    for value in _rows_v1111(values):
        for key in title_variants_v1111(value, expected_year=expected_year):
            folded = key.casefold()
            if len(folded) < 3 or folded in _GENERIC_PRIMARY_KEYS:
                continue
            return True
    return False


def has_episode_structure_v1111(values: Iterable[Any]) -> bool:
    return any(_EPISODE_EVIDENCE_RE.search(str(value or "")) for value in values or [])


def assess_media_identity_v1111(
    *,
    aliases: Sequence[str],
    expected_year: Any,
    expected_season: Any,
    is_movie: bool,
    primary_evidences: Iterable[Any] = (),
    file_evidences: Iterable[Any] = (),
    discovery_evidences: Iterable[Any] = (),
    threshold: int = 50,
) -> Dict[str, Any]:
    """硬冲突优先；其余按实际标题、弱搜索证据、年份/季号和剧集结构累计置信度。"""
    primary = _rows_v1111(primary_evidences)
    files = _rows_v1111(file_evidences)
    discovery = _rows_v1111(discovery_evidences)
    actual = primary + files
    year = str(expected_year or "").strip()
    try:
        season = int(expected_season or 0)
    except (TypeError, ValueError):
        season = 0

    years = explicit_years_v1111(actual, aliases)
    if year and years and year not in years:
        return {
            "ok": False, "hard_conflict": True, "score": 0,
            "reason_code": "YEAR_MISMATCH",
            "stage": "IDENTITY",
            "reason": f"实际资源年份冲突：期望={year} 实际={','.join(sorted(years))}",
            "evidence": {"expected_year": year, "actual_years": sorted(years)},
        }

    seasons = explicit_seasons_v1111(actual)
    if is_movie and seasons:
        return {
            "ok": False, "hard_conflict": True, "score": 0,
            "reason_code": "SEASON_MISMATCH",
            "stage": "IDENTITY",
            "reason": f"电影资源出现季号：{sorted(seasons)}",
            "evidence": {"expected_season": 0, "actual_seasons": sorted(seasons)},
        }
    if not is_movie and season > 0 and seasons and season not in seasons:
        return {
            "ok": False, "hard_conflict": True, "score": 0,
            "reason_code": "SEASON_MISMATCH",
            "stage": "IDENTITY",
            "reason": f"实际资源季号冲突：期望=S{season:02d} 实际={sorted(seasons)}",
            "evidence": {"expected_season": season, "actual_seasons": sorted(seasons)},
        }

    primary_match = any_alias_title_match_v1111(aliases, primary, expected_year=year)
    file_match = any_alias_title_match_v1111(aliases, files, expected_year=year)
    discovery_match = any_alias_title_match_v1111(aliases, discovery, expected_year=year)

    # 顶层真实分享名/解析名如果明确指向另一作品，搜索卡片绝不能把它救回来。
    if primary and not primary_match and _credible_primary_title_v1111(primary, expected_year=year):
        preview = " | ".join(primary[:3])[:220]
        return {
            "ok": False, "hard_conflict": True, "score": 0,
            "reason_code": "MEDIA_IDENTITY_UNCONFIRMED",
            "stage": "IDENTITY",
            "reason": f"实际资源顶层标题与订阅不一致：{preview}",
            "evidence": {"primary": primary[:3]},
        }

    score = 0
    reasons: List[str] = []
    if primary_match:
        score += 60
        reasons.append("实际分享/解析标题匹配+60")
    if file_match:
        score += 40
        reasons.append("实际文件路径标题匹配+40")
    if discovery_match:
        score += 35
        reasons.append("搜索发现标题匹配+35")
    if files:
        score += 5
        reasons.append("已取得实际文件列表+5")
    if year and years and year in years:
        score += 10
        reasons.append("实际年份匹配+10")
    if not is_movie and season > 0 and seasons and season in seasons:
        score += 10
        reasons.append("实际季号匹配+10")
    if not is_movie and has_episode_structure_v1111(files):
        score += 15
        reasons.append("实际文件含剧集结构+15")

    score = min(100, score)
    required = max(1, int(threshold or 50))
    if score >= required:
        if season > 1 and not seasons:
            reasons.append("季号缺失但无冲突，按多证据置信度放行")
        reason_code = "OFFICIAL_ALIAS_MATCH" if discovery_match and not primary_match else "TITLE_MATCH"
        return {
            "ok": True, "hard_conflict": False, "score": score,
            "reason_code": reason_code,
            "stage": "IDENTITY",
            "reason": "；".join(reasons) or f"媒体身份置信度={score}",
            "primary_match": primary_match, "file_match": file_match,
            "discovery_match": discovery_match, "years": sorted(years), "seasons": sorted(seasons),
        }

    preview = " | ".join((primary + files[:3] + discovery[:2])[:6])[:260]
    return {
        "ok": False, "hard_conflict": False, "score": score,
        "reason_code": "MEDIA_IDENTITY_UNCONFIRMED",
        "stage": "IDENTITY",
        "reason": f"媒体身份置信度不足：{score}<{required}；{preview}",
        "primary_match": primary_match, "file_match": file_match,
        "discovery_match": discovery_match, "years": sorted(years), "seasons": sorted(seasons),
    }


def validate_media_evidence_v1111(
    *,
    aliases: Sequence[str],
    expected_year: Any,
    expected_season: Any,
    is_movie: bool,
    evidences: Iterable[Any],
    require_title: bool = True,
    require_explicit_season: bool = False,
) -> tuple[bool, str]:
    """兼容旧严格调用；v1.11.1 自动来源使用 assess_media_identity_v1111。"""
    rows = _rows_v1111(evidences)
    if not rows:
        return False, "实际资源没有可校验的标题或文件路径"
    year = str(expected_year or "").strip()
    years = explicit_years_v1111(rows, aliases)
    if year and years and year not in years:
        return False, f"实际资源年份冲突：期望={year} 实际={','.join(sorted(years))}"
    seasons = explicit_seasons_v1111(rows)
    try:
        season = int(expected_season or 0)
    except (TypeError, ValueError):
        season = 0
    if is_movie and seasons:
        return False, f"电影资源出现季号：{sorted(seasons)}"
    if not is_movie and season > 0 and seasons and season not in seasons:
        return False, f"实际资源季号冲突：期望=S{season:02d} 实际={sorted(seasons)}"
    if not is_movie and require_explicit_season and season > 1 and not seasons:
        return False, f"S{season:02d} 自动转存要求实际资源包含明确季号，当前资源缺少季号证据"
    if require_title and not any_alias_title_match_v1111(aliases, rows, expected_year=year):
        preview = " | ".join(rows[:4])[:220]
        return False, f"实际资源标题无法确认属于当前媒体：{preview}"
    return True, "实际资源标题/年份/季号校验通过"


_TMDB_MARKER_RE = re.compile(
    r"(?ix)"
    r"(?:\{?\s*tmdb(?:[_-]id)?\s*[=:\-]?\s*(\d{1,12})\s*\}?)"
    r"|"
    r"(?:\{?\s*tmdbid\s*[=:\-]?\s*(\d{1,12})\s*\}?)"
)


def extract_share_media_identity_v1111(evidences: Iterable[Any]) -> Dict[str, Any]:
    """从分享真实路径/顶层名提取 TMDB marker 与标题候选。"""
    tmdb_ids: List[str] = []
    title_candidates: List[str] = []
    top_level_names: List[str] = []
    seen_tmdb: Set[str] = set()
    seen_titles: Set[str] = set()
    for raw in evidences or []:
        for text in _candidate_strings(raw):
            for match in _TMDB_MARKER_RE.finditer(text):
                value = str(match.group(1) or match.group(2) or "").strip()
                if value and value not in seen_tmdb:
                    seen_tmdb.add(value)
                    tmdb_ids.append(value)
            cleaned = re.sub(r"(?i)\{\s*tmdb(?:[_-]?id)?\s*[=:\-]?\s*\d{1,12}\s*\}", " ", text)
            cleaned = re.sub(r"(?i)\btmdb(?:[_-]?id)?\s*[=:\-]?\s*\d{1,12}\b", " ", cleaned)
            for part in _candidate_strings(cleaned):
                key = part.casefold()
                if len(part) >= 2 and key not in seen_titles:
                    seen_titles.add(key)
                    title_candidates.append(part)
            try:
                top = PurePosixPath(text.replace("\\", "/")).parts[0]
            except Exception:
                top = text.split("/", 1)[0].strip()
            if top and top.casefold() not in {row.casefold() for row in top_level_names}:
                top_level_names.append(top)
    return {
        "tmdb_id": tmdb_ids[0] if len(tmdb_ids) == 1 else (tmdb_ids[0] if tmdb_ids else ""),
        "tmdb_ids": tmdb_ids,
        "title_candidates": title_candidates,
        "top_level_names": top_level_names,
    }


__all__ = [
    "explicit_seasons_v1111",
    "explicit_years_v1111",
    "title_key_v1111",
    "title_variants_v1111",
    "strong_title_match_v1111",
    "any_alias_title_match_v1111",
    "has_episode_structure_v1111",
    "assess_media_identity_v1111",
    "validate_media_evidence_v1111",
    "extract_share_media_identity_v1111",
]

media_match_v11219:
"""v1.12.19 高质量媒体匹配与强 claim 语义。

这一层只做两件事：
1. 电影：真正执行前必须从真实分享/resolve 结果中得到可验证的视频与作品标题证据；
2. 剧集/动漫：把“想补哪些集”与“真实解析后确认哪些集”彻底分开，只有已经
   resolve 并准备/已经提交给光鸭的物理集，才形成跨来源强 claim。

兼容原则：
- target_episodes 继续保留，作为旧 UI / 持久化兼容字段，但只表示 requested intent；
- requested_episodes 表示本次希望补的集；
- candidate_episodes 仅表示搜索标题/帖子中可高置信推断出的候选集；
- resolved_episodes 表示真实 payload 中确认的集；
- transfer_episodes 表示最终允许提交给光鸭的物理集；
- 老版本已经存在 taskId 但没有新字段时，submitted/queued/waiting/completed 仍可回退
  target_episodes 形成 claim，避免升级后把既有远端任务误当成不存在。
"""
from __future__ import annotations

import time
from typing import Any, Dict, Iterable, List, Set

from .episode_resolver_v190 import AUTO_SELECT_CONFIDENCE, reliable_episode_set, resolve_episode
from .legacy import _is_video
from .media_identity_v1111 import assess_media_identity_v1111


_STRONG_SOURCE_STATES_V11219 = {"submitted", "queued", "waiting", "completed"}
_ACTIVE_SOURCE_STATES_V11219 = {
    "new", "retry", "dispatching", "submitted", "queued", "waiting", "completed"
}


def _positive_episode_set_v11219(values: Iterable[Any]) -> Set[int]:
    result: Set[int] = set()
    for raw in values or []:
        try:
            value = int(raw or 0)
        except (TypeError, ValueError):
            continue
        if value > 0:
            result.add(value)
    return result


def source_claim_episodes_v11219(source: Dict[str, Any]) -> Set[int]:
    """只返回已经具备强执行事实的集数；new/retry 的意图绝不占坑。"""
    row = dict(source or {})
    state = str(row.get("state") or "new").strip().lower()
    verified = _positive_episode_set_v11219(row.get("transfer_episodes") or [])
    if not verified:
        verified = _positive_episode_set_v11219(row.get("resolved_episodes") or [])

    if state in _STRONG_SOURCE_STATES_V11219:
        if verified:
            return verified
        # 升级兼容：旧版本 task 已经真实存在但没有 resolved/transfer 字段。
        if str(row.get("task_id") or "").strip():
            return _positive_episode_set_v11219(row.get("target_episodes") or [])
        return set()

    # dispatching 只有已经通过真实 payload 验证时才允许成为强 claim。
    if state == "dispatching" and bool(row.get("media_match_verified_v11219")):
        return verified
    return set()


def movie_actual_match_v11219(
    *,
    aliases: Iterable[str],
    expected_year: Any,
    primary_evidences: Iterable[Any],
    file_evidences: Iterable[Any],
) -> Dict[str, Any]:
    """电影最终身份只看真实 payload，不允许 discovery 单独把资源救回来。"""
    alias_rows = [str(value or "").strip() for value in aliases or [] if str(value or "").strip()]
    primary = [str(value or "").strip() for value in primary_evidences or [] if str(value or "").strip()]
    files = [str(value or "").strip() for value in file_evidences or [] if str(value or "").strip()]
    assessment = assess_media_identity_v1111(
        aliases=alias_rows,
        expected_year=expected_year,
        expected_season=0,
        is_movie=True,
        primary_evidences=primary,
        file_evidences=files,
        discovery_evidences=(),
        threshold=45,
    )
    actual_title_match = bool(assessment.get("primary_match") or assessment.get("file_match"))
    if not bool(assessment.get("ok")) or not actual_title_match:
        reason = str(assessment.get("reason") or "真实电影身份不足")
        if bool(assessment.get("ok")) and not actual_title_match:
            reason = "真实 payload 没有命中任何 MoviePilot/TMDB 官方标题别名"
        return {
            **dict(assessment),
            "ok": False,
            "actual_title_match": actual_title_match,
            "reason": reason,
        }
    return {
        **dict(assessment),
        "ok": True,
        "actual_title_match": True,
    }


class GuangYaMediaMatchV11219Mixin:
    """电影作品身份 + 剧集物理集两条最终匹配链的共同收口。"""

    match_schema_v11219 = 1
    _completed_claim_grace_seconds_v11219 = 15 * 60

    def _candidate_episode_set_v11219(
        self,
        subscribe: Any,
        *,
        label: str = "",
        episode_hint: str = "",
    ) -> Set[int]:
        if subscribe is None or self._is_movie_subscription(subscribe):
            return set()
        paths = [value for value in (str(label or "").strip(), str(episode_hint or "").strip()) if value]
        result: Set[int] = set()
        threshold = float(getattr(self, "_episode_auto_confidence", AUTO_SELECT_CONFIDENCE) or AUTO_SELECT_CONFIDENCE)
        for value in paths:
            try:
                parsed = resolve_episode(
                    value,
                    package_paths=paths,
                    season_hint=getattr(subscribe, "season", None),
                    episode_hint=str(episode_hint or ""),
                )
                result.update(reliable_episode_set(parsed, threshold))
            except Exception:
                continue
        return result

    def _upsert_source(self, *args: Any, **kwargs: Any):
        """保存 requested/candidate intent；不把它们提升成已验证 claim。"""
        row = dict(super()._upsert_source(*args, **kwargs) or {})
        if not row:
            return row

        subscribe_id = int(row.get("subscribe_id") or (args[0] if args else kwargs.get("subscribe_id") or 0) or 0)
        subscribe = self._find_subscription(subscribe_id) if subscribe_id else None
        is_movie = bool(subscribe is not None and self._is_movie_subscription(subscribe))
        requested = set()
        if not is_movie:
            requested = _positive_episode_set_v11219(
                kwargs.get("target_episodes")
                if "target_episodes" in kwargs
                else row.get("requested_episodes") or row.get("target_episodes") or []
            )
        candidate = self._candidate_episode_set_v11219(
            subscribe,
            label=str(kwargs.get("label") or row.get("label") or row.get("name") or ""),
            episode_hint=str(kwargs.get("episode_hint") or row.get("episode_hint") or ""),
        )

        fields: Dict[str, Any] = {
            "match_schema_v11219": int(self.match_schema_v11219),
            "media_scope_v11219": "movie" if is_movie else "series",
            "requested_episodes": sorted(requested),
            "candidate_episodes": sorted(candidate),
        }
        if "media_match_verified_v11219" not in row:
            fields["media_match_verified_v11219"] = False
        updated = self._update_source(str(row.get("id") or ""), **fields)
        return dict(updated or row)

    def _active_source_claims(self, subscribe_id: int) -> Set[int]:
        return self._effective_source_claims_v11222(subscribe_id)

    def _effective_source_claims_v11222(self, subscribe_id: int, current_source_id: str = "") -> Set[int]:
        """Planning and final payload checks must use the same claim lifetime."""
        claims: Set[int] = set()
        sid = int(subscribe_id or 0)
        subscribe = self._find_subscription(sid) if sid else None
        missing_now: Set[int] = set()
        if subscribe is not None and not self._is_movie_subscription(subscribe):
            for raw in (self._subscription_missing_episodes(subscribe) or []):
                try:
                    value = int(raw or 0)
                except (TypeError, ValueError):
                    continue
                if value > 0:
                    missing_now.add(value)
        try:
            items = (self._source_store().get("items") or {}).values()
        except Exception:
            return claims
        for row in items:
            if not isinstance(row, dict) or int(row.get("subscribe_id") or 0) != sid:
                continue
            if current_source_id and str(row.get("id") or "") == str(current_source_id):
                continue
            if not bool(row.get("enabled", True)):
                continue
            row_claims = source_claim_episodes_v11219(row)
            if not row_claims:
                continue
            state = str(row.get("state") or "").strip().lower()
            overlap = row_claims.intersection(missing_now)
            if state == "completed" and overlap:
                try:
                    completed_ts = float(row.get("completed_ts") or 0)
                except (TypeError, ValueError):
                    completed_ts = 0.0
                grace = max(60, int(getattr(self, "_completed_claim_grace_seconds_v11219", 15 * 60) or 15 * 60))
                if completed_ts <= 0:
                    try:
                        self._plugin_log(
                            "INFO",
                            "【光鸭转存助手】【来源Claim】#%s 释放无 completed_ts 的 completed 占坑：source=%s episodes=%s",
                            sid,
                            str(row.get("id") or "-")[:60],
                            sorted(overlap),
                        )
                    except Exception:
                        pass
                    row_claims = row_claims - overlap
                    if not row_claims:
                        continue
                if completed_ts > 0 and time.time() - completed_ts >= grace:
                    try:
                        self._plugin_log(
                            "INFO",
                            "【光鸭转存助手】【来源Claim】#%s 释放过期 completed 占坑：source=%s episodes=%s age=%ss",
                            sid,
                            str(row.get("id") or "-")[:60],
                            sorted(overlap),
                            int(time.time() - completed_ts),
                        )
                    except Exception:
                        pass
                    row_claims = row_claims - overlap
                    if not row_claims:
                        continue
            claims.update(row_claims)
        return claims

    def _other_source_claims_v11214(self, subscribe_id: int, current_source_id: str = "") -> Set[int]:
        return self._effective_source_claims_v11222(subscribe_id, current_source_id)

    @staticmethod
    def _source_episode_targets_v1124(source: Dict[str, Any]) -> Set[int]:
        """EpisodeFence 只对真实提交集做取消/裁剪；未验证 intent 不再形成跨来源终止事实。"""
        return source_claim_episodes_v11219(source)

    def _movie_actual_gate_v11219(
        self,
        subscribe: Any,
        *,
        primary: Iterable[Any],
        files: Iterable[Any],
        origin: str,
    ) -> Dict[str, Any]:
        aliases_fn = getattr(self, "_identity_aliases_v1111", None)
        aliases = list(aliases_fn(subscribe) if callable(aliases_fn) else [str(getattr(subscribe, "name", "") or "")])
        assessment = movie_actual_match_v11219(
            aliases=aliases,
            expected_year=getattr(subscribe, "year", None),
            primary_evidences=primary,
            file_evidences=files,
        )
        if not bool(assessment.get("ok")):
            self._plugin_log(
                "WARNING",
                "【光鸭转存助手】【电影最终匹配v1.12.19】#%s %s origin=%s 拒绝：%s",
                int(getattr(subscribe, "id", 0) or 0),
                str(getattr(subscribe, "name", "") or ""),
                str(origin or "-")[:40],
                str(assessment.get("reason") or "")[:320],
