        return assessment

    def _plan_incremental_files(
        self,
        probe: Dict[str, Any],
        assets: Dict[str, Any],
        subscribe: Any = None,
        target_path: str = "",
        stats: Dict[str, Any] | None = None,
    ):
        planned = list(super()._plan_incremental_files(
